package com.oms.supplychain;
import com.oms.supplychain.service.wms.*;
import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.supplychain.service.wms.WmsStore.*;
class WmsProcessTest {
 PurchaseWorkspaceTest f;WmsProcessService service;ProcessStockClient stock;WmsConnections connections;
 @BeforeAll static void start(){PurchaseWorkspaceTest.init();}
 @AfterAll static void stop(){PurchaseWorkspaceTest.shutdown();}
 @BeforeEach void setup(){f=new PurchaseWorkspaceTest();for(String t:Arrays.asList("wms_process_event","wms_process_order","goods_bundle_component","goods_bundle_version","goods_bundle","goods_sku_sn_info"))f.db.update("DELETE FROM "+t);f.seed();service=new WmsProcessService();stock=mock(ProcessStockClient.class);connections=f.context.getBean(WmsConnections.class);ReflectionTestUtils.setField(service,"db",f.context.getBean(WmsStore.class));ReflectionTestUtils.setField(service,"connections",connections);ReflectionTestUtils.setField(service,"logs",f.context.getBean(WmsInteractionLog.class));ReflectionTestUtils.setField(service,"protocol",new QimenProcessProtocol());ReflectionTestUtils.setField(service,"qimen",new QimenProtocol());ReflectionTestUtils.setField(service,"stock",stock);}
 @Test void missingWarehouseCapabilityIsExplicitAndCannotReserve(){assertThrows(IllegalArgumentException.class,()->service.create("QM",map("operation","ASSEMBLE","sku_sn","S","store_code","V","quantity",1,"request_key","T1","reason","test"),"tester"));verifyNoInteractions(stock);}
 @Test void partialStockReplyCreatesTwoNonDispatchingVouchersAndRetryDoesNotDuplicate(){long cfg=connections.save("QM",map("name","process","provider","QIMEN","api_version","2.0","environment","TEST","endpoint","http://localhost:9999","app_key","app","secret","secret","customer_id","customer","enabled",1,"storeprocess_enabled",1));WmsStore db=f.context.getBean(WmsStore.class);long key=db.insert("wms_process_order",map("company_code","QM","process_sn","JGTEST","request_key","T2","request_hash","h","operation","ASSEMBLE","sku_sn","S","goods_name","S","revision",1,"recipe_json","{\"sku_sn\":\"S\",\"inventory_mode\":\"STOCKED\",\"revision\":1,\"components\":[{\"sku_sn\":\"A\",\"quantity\":2}]}","quantity",2,"store_code","V","real_store_code","W","owner_code","O","connection_id",cfg,"external_warehouse","W","external_owner","O","state","READY","dispatch_state","ACCEPTED","external_order","W123","reason","test","created_by","test"));Map<String,Object> payload=map("process_sn","JGTEST","message_id","M1","quantity",1,"inputs",Arrays.asList(map("sku_sn","A","batch_code","A1","inventory_type","ZP","quantity",2)),"outputs",Arrays.asList(map("sku_sn","S","batch_code","S1","inventory_type","ZP","quantity",1)));long event=db.insert("wms_process_event",map("company_code","QM","process_id",key,"message_id","M1","payload_hash","h","payload_json",db.encode(payload),"quantity",1,"source_log_id",0));when(stock.execute(eq("QM"),eq("post"),anyMap())).thenReturn(R.ok(map("completed_quantity",1,"state","PARTIAL","holds",Arrays.asList(),"events",Arrays.asList())));service.retryEvent("QM",key,event,false,"","tester");service.retryEvent("QM",key,event,false,"","tester");verify(stock,times(1)).execute(eq("QM"),eq("post"),anyMap());assertEquals(2,f.db.queryForObject("SELECT COUNT(*) FROM wms_tickets WHERE relation_sn='JGTEST'",Integer.class));assertEquals(2,f.db.queryForObject("SELECT SUM(inventory_is_handle=2) FROM wms_tickets_goods WHERE sn LIKE 'JGTEST%'",Integer.class));assertEquals("PARTIAL",service.detail("QM",key).get("state"));payload.put("message_id","M2");long second=db.insert("wms_process_event",map("company_code","QM","process_id",key,"message_id","M2","payload_hash","h2","payload_json",db.encode(payload),"quantity",1,"source_log_id",0));when(stock.execute(eq("QM"),eq("post"),anyMap())).thenReturn(R.ok(map("completed_quantity",2,"state","COMPLETED","holds",Collections.emptyList(),"events",Collections.emptyList())));service.retryEvent("QM",key,second,false,"","tester");assertEquals(4,f.db.queryForObject("SELECT COUNT(*) FROM wms_tickets WHERE relation_sn='JGTEST'",Integer.class));assertEquals("COMPLETED",service.detail("QM",key).get("state"));long ticket=f.db.queryForObject("SELECT id FROM wms_tickets WHERE relation_sn='JGTEST' AND business_type='ASSEMBLY_IN' ORDER BY id LIMIT 1",Long.class);Map<String,Object> voucher=f.service.detail("QM","ticket",ticket);assertEquals("加工记账凭证",voucher.get("modeLabel"));assertEquals(1L,((Number)((Map<?,?>)((List<?>)voucher.get("lines")).get(0)).get("numberPosted")).longValue());assertEquals(1L,((Number)f.service.receiptBatches("QM",ticket,1,20).getTotal()).longValue());}
}
